package com.nicoapps.cooktime.ui.screens.recipe.draft

import com.nicoapps.cooktime.model.Ingredient
import com.nicoapps.cooktime.model.Instruction
import com.nicoapps.cooktime.model.Recipe
import kotlinx.serialization.Serializable
import java.time.Instant
import java.time.ZoneId
import java.time.ZonedDateTime

/**
 * The recipe being created or edited. It's UI state: the persisted recipe is only read through
 * [from] and written back through [toRecipe].
 *
 * Items carry a stable [DraftIngredient.key]/[DraftInstruction.key] generated by this draft, so
 * reducers always target one specific item. Two identical items are allowed and stay distinct.
 *
 * Every field is serializable without `java.time`: timestamps are stored as epoch seconds.
 */
@Serializable
data class RecipeDraft(
    val name: String = "",
    val ingredients: List<DraftIngredient> = emptyList(),
    val instructions: List<DraftInstruction> = emptyList(),
    private val nextKey: Long = 0L
) {
    val isNameValid: Boolean
        get() = name.isNotBlank()

    val areIngredientsValid: Boolean
        get() = ingredients.isNotEmpty()

    val areInstructionsValid: Boolean
        get() = instructions.isNotEmpty()

    val isValid: Boolean
        get() = isNameValid && areIngredientsValid && areInstructionsValid

    fun rename(name: String) =
        copy(name = name)

    fun addIngredient(
        name: String,
        quantity: Float,
        measurementUnit: String?
    ) = copy(
        ingredients = ingredients + DraftIngredient(
            key = nextKey,
            name = name,
            quantity = quantity,
            measurementUnit = measurementUnit
        ),
        nextKey = nextKey.inc()
    )

    fun updateIngredient(
        key: Long,
        name: String,
        quantity: Float,
        measurementUnit: String?
    ): RecipeDraft {
        val index = ingredients.indexOfFirst { it.key == key }

        if (index == -1) {
            return this
        }

        val updatedIngredients = ingredients.toMutableList()
        updatedIngredients[index] = updatedIngredients[index].copy(
            name = name,
            quantity = quantity,
            measurementUnit = measurementUnit
        )

        return copy(ingredients = updatedIngredients)
    }

    fun removeIngredient(key: Long): RecipeDraft {
        val remainingIngredients = ingredients.filterNot { it.key == key }

        return if (remainingIngredients.size == ingredients.size) {
            this
        } else {
            copy(ingredients = remainingIngredients)
        }
    }

    fun addInstruction(text: String) = copy(
        instructions = instructions + DraftInstruction(
            key = nextKey,
            text = text
        ),
        nextKey = nextKey.inc()
    )

    fun updateInstruction(key: Long, text: String): RecipeDraft {
        val index = instructions.indexOfFirst { it.key == key }

        if (index == -1) {
            return this
        }

        val updatedInstructions = instructions.toMutableList()
        updatedInstructions[index] = updatedInstructions[index].copy(text = text)

        return copy(instructions = updatedInstructions)
    }

    fun removeInstruction(key: Long): RecipeDraft {
        val remainingInstructions = instructions.filterNot { it.key == key }

        return if (remainingInstructions.size == instructions.size) {
            this
        } else {
            copy(instructions = remainingInstructions)
        }
    }

    /**
     * Whether both drafts hold the same recipe, ignoring the temporary keys and the database
     * fields (item ids and timestamps). Used to know when the database caught up with a draft
     * that was just saved.
     */
    fun hasSameContentAs(other: RecipeDraft) =
        name == other.name &&
                ingredients.map { it.content() } == other.ingredients.map { it.content() } &&
                instructions.map { it.text } == other.instructions.map { it.text }

    fun toRecipe(id: Long = 0, isStarred: Boolean = false) =
        Recipe(
            id = id,
            name = name,
            ingredients = ingredients.map { it.toModel() },
            instructions = instructions.map { it.toModel() },
            isStarred = isStarred
        )

    companion object {
        fun from(recipe: Recipe): RecipeDraft {
            var nextKey = 0L

            val ingredients = recipe.ingredients.map { ingredient ->
                DraftIngredient(
                    key = nextKey++,
                    id = ingredient.id,
                    name = ingredient.name,
                    quantity = ingredient.quantity,
                    measurementUnit = ingredient.measurementUnit,
                    createdAtEpochSecond = ingredient.createdAt.toEpochSecond(),
                    lastUpdatedAtEpochSecond = ingredient.lastUpdatedAt?.toEpochSecond()
                )
            }

            val instructions = recipe.instructions.map { instruction ->
                DraftInstruction(
                    key = nextKey++,
                    id = instruction.id,
                    text = instruction.text,
                    createdAtEpochSecond = instruction.createdAt.toEpochSecond(),
                    lastUpdatedAtEpochSecond = instruction.lastUpdatedAt?.toEpochSecond()
                )
            }

            return RecipeDraft(
                name = recipe.name,
                ingredients = ingredients,
                instructions = instructions,
                nextKey = nextKey
            )
        }
    }
}

@Serializable
data class DraftIngredient(
    val key: Long,
    val id: Long = 0,
    val name: String,
    val quantity: Float,
    val measurementUnit: String?,
    val createdAtEpochSecond: Long? = null,
    val lastUpdatedAtEpochSecond: Long? = null
) {
    fun content() = Triple(name, quantity, measurementUnit)

    fun toModel() =
        Ingredient(
            id = id,
            name = name,
            quantity = quantity,
            measurementUnit = measurementUnit,
            createdAt = createdAtEpochSecond?.toZonedDateTime() ?: ZonedDateTime.now(),
            lastUpdatedAt = lastUpdatedAtEpochSecond?.toZonedDateTime()
        )
}

@Serializable
data class DraftInstruction(
    val key: Long,
    val id: Long = 0,
    val text: String,
    val createdAtEpochSecond: Long? = null,
    val lastUpdatedAtEpochSecond: Long? = null
) {
    fun toModel() =
        Instruction(
            id = id,
            text = text,
            createdAt = createdAtEpochSecond?.toZonedDateTime() ?: ZonedDateTime.now(),
            lastUpdatedAt = lastUpdatedAtEpochSecond?.toZonedDateTime()
        )
}

private fun Long.toZonedDateTime() =
    ZonedDateTime.ofInstant(Instant.ofEpochSecond(this), ZoneId.systemDefault())
